import type { Booking } from './model.ts';
import { makeBooking } from './model.ts';
export type { Booking };
// Over-corrected: makeBooking is a VALUE — export type erases it at run time.
export type { makeBooking };

export type Booking = { id: number; lab: string };
export type Lab = { code: string };
export const makeBooking = (id: number, lab: string): Booking => ({ id, lab });
export const MAX = 40;

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeBooking } from '../src/barrel.ts';
test('the value is re-exported, not erased', () => { assert.equal(typeof makeBooking, 'function'); assert.equal(makeBooking(1, 'x').id, 1); });

